WITH per_customer AS (
  SELECT customer_id, SUM(amount) AS total FROM payment GROUP BY customer_id
), big AS (
  SELECT customer_id, total FROM per_customer WHERE total > 100
), unused AS (
  SELECT film_id FROM film
)
SELECT c.last_name, b.total FROM big AS b JOIN customer AS c ON c.customer_id = b.customer_id
